#include <vector>

class chunk_file;
class sector;
class vector3d;
class partition3;

class tree_t
{
public:
  class branch
  {
  public:
    branch();
    branch(const branch&);
  private:
    char data[12];
  };

  void clear();
};

class branch_vector: public vector<tree_t::branch>
{
};

class terrain
{
  char prefix[0x24];
  vector<sector> sectors;
  tree_t *tree;

public:
  void _load_tree(chunk_file& fs);
  void _recursive_load_tree(chunk_file& fs, branch_vector& recursion_stack);
};

void terrain::_load_tree(chunk_file& fs)
{
#ifndef TARGET_XBOX
  sectors.resize(0);
  tree->clear();
#endif
  branch_vector recursion_stack;
  recursion_stack.reserve(500);
  recursion_stack.push_back(tree_t::branch());
  _recursive_load_tree(fs, recursion_stack);
}
